// Refund a captured payment via the Payments v2 API.
// The default request id is derived from the capture so a retried full refund
// reuses it and PayPal returns the original result instead of refunding again.
// Partial refunds must pass an id from their own refund record instead.
export async function refundCapture(captureId, amount, requestId = `refund-${captureId}`) {
  const accessToken = await generateAccessToken();
  const response = await fetch(`${base}/v2/payments/captures/${captureId}/refund`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${accessToken}`,
      "PayPal-Request-Id": requestId,
    },
